<!doctype html>
<html>
  <head>
    <title>My Website</title>
    <link rel="stylesheet" href="style.css">
  </head>
  <body>
    <div class="container">
      <h1>Hello World!</h1>
      <p>This is my website.</p>
    </div>
  </body>
</html>
```
